static uint32_t shade(uint32_t c,int d){int r=(c&255)+d,gg=((c>>8)&255)+d,b=((c>>16)&255)+d;return C(r<0?0:r>255?255:r,gg<0?0:gg>255?255:gg,b<0?0:b>255?255:b);}
static void rect(int x,int y,int w,int h,uint32_t c){if(x<0){w+=x;x=0;}if(y<0){h+=y;y=0;}if(x+w>480)w=480-x;if(y+h>272)h=272-y;if(w<=0||h<=0)return;for(int j=0;j<h;j++){uint32_t *r=fb+(y+j)*pitch+x;for(int i=0;i<w;i++)r[i]=c;}}
static void pixel(int x,int y,uint32_t c){if(x>=0&&x<480&&y>=0&&y<272)fb[y*pitch+x]=c;}
static void line(int x0,int y0,int x1,int y1,uint32_t c){int dx=abs(x1-x0),sx=x0<x1?1:-1,dy=-abs(y1-y0),sy=y0<y1?1:-1,er=dx+dy;for(;;){pixel(x0,y0,c);if(x0==x1&&y0==y1)break;int e=er*2;if(e>=dy){er+=dy;x0+=sx;}if(e<=dx){er+=dx;y0+=sy;}}}
static void circle(int x,int y,int r,uint32_t c){for(int j=-r;j<=r;j++){int w=(int)sqrtf((float)(r*r-j*j));rect(x-w,y+j,w*2+1,1,c);}}
static void ellipse(int x,int y,int w,int h,uint32_t c){for(int j=-h;j<=h;j++){int v=(int)(w*sqrtf(1-(float)(j*j)/(h*h)));rect(x-v,y+j,v*2+1,1,c);}}
static void border(int x,int y,int w,int h,uint32_t c){rect(x,y,w,1,c);rect(x,y+h-1,w,1,c);rect(x,y,1,h,c);rect(x+w-1,y,1,h,c);}
static void panel(int x,int y,int w,int h){rect(x+3,y+3,w,h,C(6,18,29));rect(x,y,w,h,C(16,41,54));border(x,y,w,h,C(69,117,125));rect(x,y,w,2,GREEN);}
static unsigned cp(const char **p){unsigned c=(unsigned char)*(*p)++;if(c<128)return c;if((c&224)==192){unsigned b=(unsigned char)*(*p)++;return((c&31)<<6)|(b&63);}if((c&240)==224){unsigned b=(unsigned char)*(*p)++,a=(unsigned char)*(*p)++;return((c&15)<<12)|((b&63)<<6)|(a&63);}return '?';}
static void glyph(int x,int y,unsigned c,uint32_t col,int scale){int a=0,b=GLYPH_COUNT-1;while(a<=b){int m=(a+b)/2;if(font_codes[m]==c){for(int j=0;j<14;j++)for(int i=0;i<12;i++)if(font_rows[m][j]&(1<<i))rect(x+i*scale,y+j*scale,scale,scale,col);return;}if(font_codes[m]<c)a=m+1;else b=m-1;}}
static void text(int x,int y,const char *s,uint32_t c,int limit){int start=x;while(*s&&*s!='\n'){unsigned v=cp(&s);int w=v<128?6:12;if(x+w>start+limit)break;glyph(x,y,v,c,1);x+=w;}}
static void big(int x,int y,const char *s,uint32_t c){while(*s){unsigned v=cp(&s);glyph(x,y,v,c,2);x+=v<128?12:24;}}
static void wrap(int x,int y,const char *s,uint32_t c,int width,int maxlines){int ox=x,l=0;while(*s&&l<maxlines){unsigned v=cp(&s);int w=v<128?6:12;if(v=='\n'){x=ox;y+=18;l++;continue;}if(x+w>ox+width){x=ox;y+=18;l++;if(l>=maxlines)break;}glyph(x,y,v,c,1);x+=w;}}
static void sprite(uint32_t *atlas,int aw,int sx,int sy,int w,int h,int x,int y,int flip,int clip){if(!atlas)return;for(int j=0;j<h;j++){int yy=y+j;if(yy<clip||yy>=272-(clip?24:0))continue;for(int i=0;i<w;i++){int xx=x+i;if(xx<0||xx>=480)continue;uint32_t c=atlas[(sy+j)*aw+sx+(flip?w-1-i:i)];unsigned a=c>>24;if(a>=220)fb[yy*pitch+xx]=c|0xff000000u;else if(a>40){uint32_t d=fb[yy*pitch+xx];unsigned r=((c&255)*a+(d&255)*(255-a))/255;unsigned gg=(((c>>8)&255)*a+((d>>8)&255)*(255-a))/255;unsigned b=(((c>>16)&255)*a+((d>>16)&255)*(255-a))/255;fb[yy*pitch+xx]=C(r,gg,b);}}}}
static void prop(int n,int x,int y,int clip){sprite(props,256,(n%4)*64,(n/4)*80,64,80,x-32,y-80,0,clip);}
static void hero(int n,int x,int y,int dir,int walking,int clip){int pose=dir==0?0:dir==2?2:4;if(walking&&(g.anim/7)%2)pose++;ellipse(x,y-1,14,4,C(39,62,66));sprite(heroes,288,pose*48,n*64,48,64,x-24,y-62+(walking?(g.anim/7)%2:0),dir==1,clip);}
