static void help(void){if(g.return_mode==PLAY||g.return_mode==PAUSE)world();else title_scene();panel(10,10,460,251);if(g.help_page==1&&g.return_mode!=TITLE){text(24,23,"区域地图 · 白点是你 / 金点是目标 / 绿点是出口",GOLD,438);small_map(35,46,336,180,1);text(382,58,"进度",GREEN,80);char b[25];snprintf(b,sizeof(b),"%d / %d",g.done,g.needed);text(382,80,b,WHITE,75);text(25,239,"O返回  L/R操作说明  ·  紫点/区域为污染",MUTED,435);return;}text(26,24,"操作与元素",GOLD,420);const char *rows[]={"方向键 / 摇杆：移动     L/R：切换五位队员","X：连续使用戒指     O：闪避     方块：互动","三角：能量100时召唤地球超人，持续12秒","SELECT：地图；时空关卡中用于切换时相","START：暂停 / 重试 / 声音 / 退出","土：冲击减速  火：高伤害  风：远程攻击","水：行水更快、净化脚下毒地  心：安抚救援","对照目标上方的元素字，切换队员后按方块","调查与沟通关卡：收集线索，前往绿色出口","过关自动记录星级；重开时从该关起点开始"};for(int i=0;i<10;i++)text(26,49+i*18,rows[i],i<5?WHITE:MUTED,432);text(26,239,"O返回  L/R翻页",GREEN,425);}
