void render_frame(uint32_t *frame,int stride){fb=frame;pitch=stride;rect(0,0,480,272,INK);switch(g.mode){case TITLE:title_scene();break;case SELECTOR:select_scene();break;case BRIEF:brief();break;case HELP:help();break;case CLEAR:result(1);break;case FAIL:result(0);break;case CREDITS:title_scene();panel(16,18,448,238);text(30,31,"地球超人 · 元素使命",GOLD,420);wrap(30,58,"为 Kyle 制作的 PSP 同人冒险游戏。\n动画角色与名称属于原作权利人。\n逐集文字资料：TVmaze / Wikipedia / TheTVDB。\n资料改写沿用 CC BY-SA 4.0，详见附带文档。\n角色图：参照动画截图生成并制作游戏图集。\n故事任务、地图、界面、音效与音乐为本作新增。\n113关为游戏化改编；未宣称逐集看完原片。\n角色尚未达到严格一比一原画验收。",WHITE,418,10);text(30,235,"O / X返回",GREEN,420);break;default:world();if(g.mode==PAUSE){panel(99,33,282,211);text(119,48,"暂停 · 时间停止",GOLD,245);const char *rows[]={"继续行动","地图与操作","声音","重试本集","返回剧集目录","保存并退出"};for(int i=0;i<6;i++){if(i==g.menu)rect(113,75+i*24,252,22,C(35,80,92));text(125,78+i*24,rows[i],WHITE,232);if(i==2)text(216,78+i*24,g.save.music?"开启":"关闭",GREEN,90);}}break;}}
static uint32_t *readraw(const char *dir,const char *name,size_t n){char p[600];snprintf(p,sizeof(p),"%s/%s",dir,name);FILE *f=fopen(p,"rb");if(!f)return NULL;uint32_t *d=malloc(n*4);if(!d){fclose(f);return NULL;}int ok=fread(d,4,n,f)==n;fclose(f);if(!ok){free(d);return NULL;}return d;}
int render_load(const char *dir){heroes=readraw(dir,"heroes.rgba",288*384);portraits=readraw(dir,"portraits.rgba",576*128);props=readraw(dir,"props.rgba",256*320);return heroes&&portraits&&props;}
void render_shutdown(void){free(heroes);free(portraits);free(props);heroes=portraits=props=NULL;}
